package com.pipeline.payment;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.ConcurrentHashMap;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class DeploymentBillingService {

    private static final int FAILURE_THRESHOLD = 5;
    private static final long RECOVERY_TIMEOUT_MS = 30000;
    private static final BigDecimal MAX_CHARGE_PER_DEPLOY = new BigDecimal("500.00");
    private static final BigDecimal MAX_PENDING_PER_TEAM = new BigDecimal("1000.00");

    enum CircuitState { CLOSED, OPEN, HALF_OPEN }

    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicLong lastFailureTime = new AtomicLong(0);
    private volatile CircuitState state = CircuitState.CLOSED;
    private final ConcurrentHashMap<String, BigDecimal> accountBalances = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, BigDecimal> pendingCharges = new ConcurrentHashMap<>();

    public DeploymentBillingService() {
        accountBalances.put("team-alpha", new BigDecimal("10000.00"));
        accountBalances.put("team-beta", new BigDecimal("5000.00"));
    }

    public synchronized BillingResult chargeForDeployment(String teamId, DeploymentRequest request) {
        if (state == CircuitState.OPEN) {
            if (System.currentTimeMillis() - lastFailureTime.get() > RECOVERY_TIMEOUT_MS) {
                state = CircuitState.HALF_OPEN;
            } else {
                return handleCircuitOpen(teamId, request);
            }
        }

        try {
            BigDecimal cost = calculateDeploymentCost(request);
            BigDecimal balance = accountBalances.getOrDefault(teamId, BigDecimal.ZERO);

            if (cost.compareTo(MAX_CHARGE_PER_DEPLOY) > 0) {
                return new BillingResult(false, "Exceeds max charge per deployment", BigDecimal.ZERO);
            }

            if (balance.compareTo(cost) < 0) {
                recordFailure();
                return new BillingResult(false, "Insufficient balance", BigDecimal.ZERO);
            }

            accountBalances.put(teamId, balance.subtract(cost));
            resetCircuit();
            return new BillingResult(true, "Charged successfully", cost);

        } catch (Exception e) {
            recordFailure();
            return new BillingResult(false, "Billing service error: " + e.getMessage(), BigDecimal.ZERO);
        }
    }

    private BillingResult handleCircuitOpen(String teamId, DeploymentRequest request) {
        BigDecimal estimatedCost = calculateDeploymentCost(request);
        BigDecimal cappedCost = estimatedCost.min(MAX_CHARGE_PER_DEPLOY);
        BigDecimal currentPending = pendingCharges.getOrDefault(teamId, BigDecimal.ZERO);
        BigDecimal balance = accountBalances.getOrDefault(teamId, BigDecimal.ZERO);

        if (currentPending.add(cappedCost).compareTo(MAX_PENDING_PER_TEAM) > 0) {
            return new BillingResult(false, "Pending charge limit exceeded", BigDecimal.ZERO);
        }
        if (currentPending.add(cappedCost).compareTo(balance) > 0) {
            return new BillingResult(false, "Insufficient balance for deferred charge", BigDecimal.ZERO);
        }

        pendingCharges.merge(teamId, cappedCost, BigDecimal::add);
        return new BillingResult(true, "Deployment queued - charge deferred", cappedCost);
    }

    public synchronized boolean reconcilePendingCharges(String teamId) {
        BigDecimal pending = pendingCharges.getOrDefault(teamId, BigDecimal.ZERO);
        if (pending.compareTo(BigDecimal.ZERO) == 0) return true;

        BigDecimal balance = accountBalances.getOrDefault(teamId, BigDecimal.ZERO);
        if (balance.compareTo(pending) < 0) {
            return false;
        }
        accountBalances.put(teamId, balance.subtract(pending));
        pendingCharges.put(teamId, BigDecimal.ZERO);
        return true;
    }

    private BigDecimal calculateDeploymentCost(DeploymentRequest request) {
        BigDecimal baseCost = new BigDecimal("10.00");
        BigDecimal instanceMultiplier = new BigDecimal(request.getInstanceCount());
        BigDecimal tierMultiplier = getTierMultiplier(request.getTier());
        BigDecimal rawCost = baseCost.multiply(instanceMultiplier).multiply(tierMultiplier);
        return rawCost.setScale(2, RoundingMode.HALF_UP);
    }

    private BigDecimal getTierMultiplier(String tier) {
        switch (tier) {
            case "gpu-large": return new BigDecimal("8.0");
            case "compute-xl": return new BigDecimal("4.0");
            case "standard": return new BigDecimal("1.0");
            default: return new BigDecimal("1.0");
        }
    }

    private void recordFailure() {
        int failures = failureCount.incrementAndGet();
        lastFailureTime.set(System.currentTimeMillis());
        if (failures >= FAILURE_THRESHOLD) {
            state = CircuitState.OPEN;
        }
    }

    private void resetCircuit() {
        failureCount.set(0);
        state = CircuitState.CLOSED;
    }

    public BigDecimal getBalance(String teamId) {
        return accountBalances.getOrDefault(teamId, BigDecimal.ZERO);
    }

    public BigDecimal getPendingCharges(String teamId) {
        return pendingCharges.getOrDefault(teamId, BigDecimal.ZERO);
    }

    public static class DeploymentRequest {
        private final int instanceCount;
        private final String tier;
        private final String pipelineId;

        public DeploymentRequest(int instanceCount, String tier, String pipelineId) {
            this.instanceCount = Math.max(1, Math.min(instanceCount, 100));
            this.tier = tier != null ? tier : "standard";
            this.pipelineId = pipelineId;
        }

        public int getInstanceCount() { return instanceCount; }
        public String getTier() { return tier; }
        public String getPipelineId() { return pipelineId; }
    }

    public static class BillingResult {
        private final boolean success;
        private final String message;
        private final BigDecimal amountCharged;

        public BillingResult(boolean success, String message, BigDecimal amountCharged) {
            this.success = success;
            this.message = message;
            this.amountCharged = amountCharged;
        }

        public boolean isSuccess() { return success; }
        public String getMessage() { return message; }
        public BigDecimal getAmountCharged() { return amountCharged; }
    }
}
